import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    blocked = [[False] * N for _ in range(M)]

    for _ in range(K):
        C = int(next(it))
        L = int(next(it))
        D = next(it)

        c = C - 1
        r = L - 1

        if D == 'N':
            for rr in range(0, r + 1):
                blocked[rr][c] = True
        elif D == 'S':
            for rr in range(r, M):
                blocked[rr][c] = True
        elif D == 'L':
            for cc in range(c, N):
                blocked[r][cc] = True
        else:  # D == 'O'
            for cc in range(0, c + 1):
                blocked[r][cc] = True

    if blocked[0][0] or blocked[M - 1][N - 1]:
        print("N")
        return

    q = deque()
    q.append((0, 0))
    seen = [[False] * N for _ in range(M)]
    seen[0][0] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        r, c = q.popleft()

        if r == M - 1 and c == N - 1:
            print("S")
            return

        for dr, dc in directions:
            nr = r + dr
            nc = c + dc

            if 0 <= nr < M and 0 <= nc < N:
                if not seen[nr][nc] and not blocked[nr][nc]:
                    seen[nr][nc] = True
                    q.append((nr, nc))

    print("N")

if __name__ == "__main__":
    main()
